import { Container, Sprite } from '../../../core/fff.js';
import { Datas } from '../../../engine/Datas.js';
import { SATCircle } from '../../../utils/SAT.js';

export class Collectable extends Container {
    constructor(pL, pC) {
        super();

        this.marked = false;
        
        this.eventMode = 'none';

        this.lig = pL;
        this.col = pC;

        this.bb = new SATCircle();
        this.bb.radius = 12;
        this.bb.x = pC * 32;
        this.bb.y = pL * 32;

        this.active = false;

        this.sp = new Sprite(Datas.atlas[Datas.COIN]);
        this.sp.anchor.set(.5);
        this.sp.scale.set(1,1);
        this.addChild(this.sp);
        this.sp.visible = true;

        this.sp2 = new Sprite(Datas.atlas[Datas.COIN]);
        this.sp2.tint = 0xDD00DD;
        this.sp2.anchor.set(.5);
        this.sp2.scale.set(2,2);
        this.addChild(this.sp2);
        this.sp2.visible = false;        
    }

    activate(){
        if(this.active == false)
        {
            this.active = true;
            this.sp.visible = false;
            this.sp2.visible = true;        
        }
    }

    deactivate(){
        if(this.active)
        {
            this.active = false;
            this.sp.visible = true;
            this.sp2.visible = false;        
        }
    }    
}