import { Container } from '../core/fff.js';

/**
 * Comme ControlableEntity, mais sur un Container : une entite controlable composee de plusieurs
 * sprites (Pixi 8 n'autorise plus d'enfants sur un Sprite).
 * Surcharger les methodes upIsDown(), action1OnPress()... voir GameInput.
 */
export class ControlableContainer extends Container {
    constructor(gameInput) {
        super();
        this._gameInput = gameInput;
        gameInput.target = this; // controlable entity
    }

    get gameInput() {
        return this._gameInput;
    }

    update() {
        // to override
    }
}

// les 28 methodes vides : upIsDown, upIsUp, upOnPress, upOnRelease, downIsDown...
['up', 'down', 'left', 'right', 'action1', 'action2', 'action3'].forEach((action) => {
    ['IsDown', 'IsUp', 'OnPress', 'OnRelease'].forEach((event) => {
        ControlableContainer.prototype[action + event] = function () { };
    });
});
