import { gsap } from 'gsap';
import { Container, Graphics, Text } from '../../../core/fff.js';
import { BT } from '../../../engine/BT.js';
import { Config } from '../../../engine/Config.js';

export class LevelHint extends Container {
    constructor(pX, pY, pMessage, pDelay = 1, pSleepDuration = 5000) {
        super();

        const MIN_W = 128, MAX_W = 176, MIN_H = 72, PAD_X = 10, PAD_Y = 14;

        let g = this.g = new Graphics();

        let textfield = new Text(pMessage, { fontFamily: Config.DEFAULT_FONT, fill: 0xFFFFFF, fontSize: 12, align: 'center', wordWrap: false, letterSpacing: 3, leading: 4, padding: 6 });
        textfield.anchor.set(.5, .5);

        // la boite s'adapte au texte (largeur 128 a 176, hauteur selon le nombre de lignes) : plus de texte coupe
        const W = Math.min(MAX_W, Math.max(MIN_W, Math.ceil(textfield.width) + PAD_X * 2));
        textfield.style.wordWrap = true;
        textfield.style.wordWrapWidth = W - PAD_X * 2;
        const H = Math.max(MIN_H, Math.ceil(textfield.height) + PAD_Y * 2);
        g.lineStyle(1, 0xFFFFFF);
        g.drawRect(0, 0, W, H);
        textfield.position.set(W / 2, H / 2);
        this.addChild(g);
        this.addChild(textfield);

        this.x = pX;
        this.y = pY;

        this.alpha = 0;

        gsap.to(this, {
            alpha: 1, y: pY - 16, delay:pDelay, duration: 1/3, ease: "power1.out"
        });

        BT.sleep(pSleepDuration).then(
                () =>{
                    // l'ecran a pu etre detruit entre-temps (changement de niveau) : plus rien a animer
                    if (this.destroyed) return;
                    gsap.to(this, {
                        alpha: 0, y: pY + 16, duration: 1, ease: "power1.out", onComplete: () => {
                            if(this.parent){
                                this.parent.removeChild(this);
                            }
                        }
                    });
                }
        )
    }
}