import { Sprite } from '../core/fff.js';
import { ClipPlayer } from './ClipPlayer.js';

/**
 * Sprite anime par etats nommes (idle, run, attack...). Remplace le basculement manuel entre plusieurs
 * sprites : un seul Sprite dont la texture change selon le clip joue.
 *
 *   const a = new Animator({
 *       idle: { frames: [texIdle] },
 *       run:  { frames: [t1, t2, t3, t4], fps: 9 }
 *   }, 'idle');
 *   a.anchor.set(.5);
 *   container.addChild(a);
 *   // a chaque frame :
 *   a.play(vitesse > 10 ? 'run' : 'idle');
 *   a.update(dt);               // dt en secondes (pas le ticker de Pixi : la pause du jeu est respectee)
 *
 * Les clips sont decrits comme pour ClipPlayer (fps, loop, next) ; a.player donne acces au lecteur
 * (speed, onComplete, finished...). Les textures viennent de Datas.atlas, d'une grille (voir sliceGrid)
 * ou d'un Spritesheet Pixi (sheet.animations['run']).
 */
export class Animator extends Sprite {
    constructor(pClips, pInitial) {
        const player = new ClipPlayer(pClips, pInitial);
        super(player.value);
        this.player = player;
    }

    get clipName() { return this.player.name; }

    play(pName, pRestart = false) {
        if (this.player.play(pName, pRestart)) this.texture = this.player.value;
    }

    update(pDt) {
        this.player.update(pDt);
        const t = this.player.value;
        if (this.texture !== t) this.texture = t;
    }
}
