// appele une fois les assets charges
const init = () => {
    // la texture "saut" est celle du dernier pas de course
    Datas.atlas[Datas.JUMP] = Datas.atlas[Datas.RUN3];

    // sons : [nom, fichier, options Howler]
    SoundManager.add(Datas.SND_BGM, '1500/sounds/Gigakoops-Level-4-Village.mp3', { loop: true, html5: true });
    SoundManager.add(Datas.SND_BONUS, '1500/sounds/pick3.wav');
    SoundManager.add(Datas.SND_JUMP, '1500/sounds/jump2.wav');
    SoundManager.add(Datas.SND_DOUBLE_JUMP, '1500/sounds/jump1.wav');
    SoundManager.add(Datas.SND_DOOR, '1500/sounds/door-open.wav');
    SoundManager.add(Datas.SND_COIN, '1500/sounds/pick1.wav');
    SoundManager.add(Datas.SND_START, '1500/sounds/start.wav');
    SoundManager.add(Datas.SND_FAIL, '1500/sounds/fail.wav');

    // touches : fleches pour courir, espace pour sauter, E = perdre une vie (debug)
    BT.getGameInput(1).changeKeyLayout('KeyW', 'KeyS', 'ArrowLeft', 'ArrowRight', 'Space', 'KeyE', 'KeyQ');
    // manette : A saute (par defaut action1 est sur X/Y)
    GameInput.PAD_MAP = [[12], [13], [14], [15], [0], [1, 3], [2, 4]];

    Datas.lives = 0;
    Datas.currentLevel = 1;
};

export const demo1500 = { id: '1500', title: '1500 (platformer)', screen: ScreenTitle, config, assets, init };
