import { moveAndCollide } from '../utils/TileCollision.js';

const approach = (pValue, pTarget, pDelta) =>
    pValue < pTarget ? Math.min(pValue + pDelta, pTarget) : Math.max(pValue - pDelta, pTarget);

/**
 * Corps de platformer : toute la "sensation" de deplacement, sans aucune dependance a Pixi.
 * A appeler a PAS FIXE (voir FixedStep) : body.step(1/60, input).
 *
 * Ce qui le rend agreable a jouer :
 *  - acceleration / friction (on ne demarre ni ne s'arrete instantanement), moins de controle en l'air ;
 *  - saut a hauteur variable : relacher la touche coupe le saut ;
 *  - coyote time : on peut encore sauter quelques ms apres avoir quitte un bord ;
 *  - jump buffer : un appui juste AVANT l'atterrissage est memorise (voir Key.pressedWithin) ;
 *  - gravite plus forte a la descente (saut "pese" moins flottant) ;
 *  - double saut, glissade le long des murs, wall jump correct (rebond oppose + courte perte de controle) ;
 *  - accroche au plafond, uniquement tant que la touche de saut est maintenue.
 *
 * Unites : pixels et secondes. Repere ecran (y vers le bas).
 *
 * input attendu : { move: -1|0|1, down: bool, jumpKey: Key (isDown, pressedWithin, consumePress) }
 * evenements : apres step(), body.events contient 'jump' | 'doubleJump' | 'wallJump' | 'land' | 'hang' | 'release'
 */
export class PlatformerBody {
    constructor(pGrid, pOptions = {}) {
        this.grid = pGrid;

        // boite de collision (centre + demi-dimensions)
        this.x = 0; this.y = 0;
        this.hw = 10; this.hh = 15;
        this.vx = 0; this.vy = 0;

        // ---- reglages ----
        this.maxRun = 190;          // px/s
        this.groundAccel = 1500;    // px/s2 : ~0.13 s pour atteindre la vitesse max
        this.groundFriction = 1700; // px/s2 : ~0.11 s pour s'arreter
        this.airAccel = 1000;
        this.airFriction = 350;     // en l'air on garde son elan
        this.turnBoost = 1.6;       // demi-tour plus nerveux

        this.gravity = 1900;        // px/s2 a la montee
        this.fallMult = 1.35;       // gravite a la descente
        this.cutMult = 3.2;         // gravite quand on relache la touche en montant (saut coupe)
        this.maxFall = 560;
        this.jumpHeight = 80;       // px, touche maintenue
        this.airJumpHeight = 64;
        this.maxAirJumps = 1;       // 1 = double saut
        this.coyoteTime = .1;       // s
        this.jumpBuffer = .12;      // s

        this.wallSlideSpeed = 70;
        this.wallJumpSpeedX = 200;
        this.wallJumpHeight = 74;
        this.wallJumpLock = .16;    // s pendant lesquelles le controle horizontal est reduit
        // saut en poussant VERS le mur : petit bond quasi vertical qui permet de grimper le long d'un mur
        // (sans cette variante, la poussee est trop forte et on retombe avant de pouvoir se rattraper)
        this.wallHopSpeedX = 70;
        this.wallHopLock = .08;
        this.wallCoyoteTime = .1;
        this.wallJumpAlternate = false; // true : deux wall jumps de suite depuis le MEME mur sont interdits
        this.hangSpeed = 110;       // vitesse de deplacement au plafond
        this.canHang = true;
        this.hangNeedsAirJump = true; // true : on ne s'accroche qu'apres un saut en l'air (double saut / wall jump) maintenu contre le plafond ;
                                      // un simple saut sous une plateforme ne fait PAS s'accrocher

        Object.assign(this, pOptions);

        // ---- etat ----
        this.onGround = false;
        this.wallDir = 0;      // -1 mur a gauche, +1 a droite (0 = aucun), en l'air seulement
        this.hanging = false;  // accroche au plafond
        this.sliding = false;  // glisse contre un mur
        this.airJumps = this.maxAirJumps;
        this.events = [];

        this._coyote = 0;
        this._wallCoyote = 0;
        this._wallSide = 0;
        this._lastWallJump = 0;
        this._lock = 0;
        this._hangBlocked = false;
        this._airJumpHeld = false;
    }

    /** vitesse initiale pour atteindre pHeight avec la gravite de montee : v = sqrt(2 g h) */
    _jumpSpeed(pHeight) { return Math.sqrt(2 * this.gravity * pHeight); }

    /** place le corps (teleportation) et remet l'etat a zero */
    reset(pX, pY) {
        this.x = pX; this.y = pY; this.vx = this.vy = 0;
        this.onGround = false; this.hanging = false; this.sliding = false; this.wallDir = 0;
        this.airJumps = this.maxAirJumps;
        this._coyote = this._wallCoyote = this._lock = 0;
        this._hangBlocked = false;
        this._lastWallJump = 0;
        this._airJumpHeld = false;
    }

    _sense() {
        const g = this.grid;
        this.onGround = g.overlaps(this, 0, 1);
        this.touchUp = g.overlaps(this, 0, -1);
        const left = g.overlaps(this, -1, 0);
        const right = g.overlaps(this, 1, 0);
        this.wallDir = this.onGround ? 0 : (right ? 1 : (left ? -1 : 0));
    }

    step(dt, input) {
        this.events.length = 0;
        const key = input.jumpKey;
        const jumpHeld = key.isDown;
        const wasGround = this.onGround;

        this._sense();

        // ---- timers & recharges ----
        if (this.onGround) {
            this._coyote = this.coyoteTime;
            this.airJumps = this.maxAirJumps;
            this._lastWallJump = 0;
            this._airJumpHeld = false;
        } else {
            this._coyote = Math.max(0, this._coyote - dt);
        }
        if (this.wallDir !== 0) {
            this.airJumps = this.maxAirJumps; // toucher un mur redonne le double saut
            this._wallCoyote = this.wallCoyoteTime;
            this._wallSide = this.wallDir;
        } else {
            this._wallCoyote = Math.max(0, this._wallCoyote - dt);
        }
        if (!jumpHeld) { this._hangBlocked = false; this._airJumpHeld = false; }

        // ---- accroche au plafond : seulement si la touche de saut est MAINTENUE ----
        if (this.hanging) {
            if (!jumpHeld || !this.touchUp || input.down) {
                if (input.down && jumpHeld) this._hangBlocked = true; // bas + saut = on se laisse tomber
                this.hanging = false;
                this.events.push('release');
            }
        } else if (this.canHang && !this.onGround && this.touchUp && jumpHeld && this.vy <= 0 && !this._hangBlocked
                   && (this._airJumpHeld || !this.hangNeedsAirJump)) {
            this.hanging = true;
            this.vy = 0;
            this.airJumps = this.maxAirJumps;
            this._lastWallJump = 0;
            key.consumePress(); // l'appui qui nous a amene ici ne doit pas redeclencher un saut
            this.events.push('hang');
        }

        // ---- saut ----
        if (!this.hanging && key.pressedWithin(this.jumpBuffer)) {
            if (this._coyote > 0) {
                key.consumePress();
                this.vy = -this._jumpSpeed(this.jumpHeight);
                this._coyote = 0;
                this.onGround = false;
                this.events.push('jump');
            } else if (this._wallCoyote > 0 && !(this.wallJumpAlternate && this._lastWallJump === this._wallSide)) {
                key.consumePress();
                this.vy = -this._jumpSpeed(this.wallJumpHeight);
                const toward = input.move === this._wallSide;
                this.vx = -this._wallSide * (toward ? this.wallHopSpeedX : this.wallJumpSpeedX);
                this._lastWallJump = this._wallSide;
                this._lock = toward ? this.wallHopLock : this.wallJumpLock;
                this._wallCoyote = 0;
                this._airJumpHeld = true;
                this.events.push('wallJump');
            } else if (!this.onGround && this.airJumps > 0) {
                key.consumePress();
                this.airJumps--;
                this.vy = -this._jumpSpeed(this.airJumpHeight);
                this._airJumpHeld = true;
                this.events.push('doubleJump');
            }
        }

        // ---- horizontal ----
        let control = 1;
        if (this._lock > 0) { this._lock -= dt; control = .2; }
        const grounded = this.onGround || this.hanging;
        const top = this.hanging ? this.hangSpeed : this.maxRun;
        if (input.move !== 0) {
            const turning = this.vx * input.move < 0;
            const a = (grounded ? this.groundAccel : this.airAccel) * (turning ? this.turnBoost : 1) * control;
            // si on depasse deja la vitesse max (wall jump), on ne force pas le ralentissement brutalement
            if (Math.abs(this.vx) <= top || turning) this.vx = approach(this.vx, input.move * top, a * dt);
            else this.vx = approach(this.vx, input.move * top, this.airFriction * dt);
        } else {
            this.vx = approach(this.vx, 0, (grounded ? this.groundFriction : this.airFriction) * control * dt);
        }

        // ---- vertical ----
        if (this.hanging) {
            this.vy = 0;
        } else {
            let g = this.gravity;
            if (this.vy > 0) g *= this.fallMult;
            else if (this.vy < 0 && !jumpHeld) g *= this.cutMult;
            this.vy = Math.min(this.vy + g * dt, this.maxFall);

            // glissade contre un mur : seulement si on pousse vers lui, et en descendant
            this.sliding = this.wallDir !== 0 && input.move === this.wallDir && this.vy > this.wallSlideSpeed;
            if (this.sliding) this.vy = this.wallSlideSpeed;
        }
        if (this.hanging) this.sliding = false;

        // ---- deplacement + collisions ----
        const hits = moveAndCollide(this, this.vx * dt, this.vy * dt, this.grid);
        if (hits.left || hits.right) this.vx = 0;
        if (hits.up) this.vy = Math.max(this.vy, 0);
        if (hits.down) {
            if (!wasGround && this.vy > 120) this.events.push('land');
            this.vy = 0;
        }
        this._sense();
    }
}
