import { Sprite, Text } from '../../../core/fff.js';
import { BaseScreen } from '../../../engine/BaseScreen.js';
import { BT } from '../../../engine/BT.js';
import { Config } from '../../../engine/Config.js';
import { Datas } from '../../../engine/Datas.js';
import { Save } from '../../../core/Save.js';
import { GameInput } from '../../../engine/GameInput.js';
import { ParticlesContainer } from '../../../engine/ParticlesContainer.js';
import { SoundManager } from '../../../engine/SoundManager.js';
import { PlatformPlayer } from '../entities/PlatformPlayer.js';
import { ScreenGame } from './ScreenGame.js';

export class ScreenTitle extends BaseScreen {
    start() {
        this._nextScreen = ScreenGame;
        super.start();
        this.visible = true;

        this.stage.addChild(Datas.atlas[Datas.BG]);

        let titleTxt = new Text("1500", { fontFamily: Config.DEFAULT_FONT, fill: 0xDD00DD, fontSize: 72, align: "center", letterSpacing: 4 });
        titleTxt.position.set(Math.floor((Config.STAGEWIDTH - titleTxt.width) / 2), Math.floor(Config.STAGEHEIGHT * 1 / 3));

        let startTxt = this.startTxt = new Text("START", { fontFamily: Config.DEFAULT_FONT, fill: 0xDD00DD, fontSize: 48, align: "center", letterSpacing: 4 });
        startTxt.position.set(Math.floor((Config.STAGEWIDTH - startTxt.width) / 2), Math.floor(Config.STAGEHEIGHT * 2 / 3));
        startTxt.visible = false;

        let insertCoinTxt = this.insertCoinTxt = new Text("INSERT COIN", { fontFamily: Config.DEFAULT_FONT, fill: 0xDDDDDD, fontSize: 24, letterSpacing: 4 });
        insertCoinTxt.position.set(Math.floor(Config.STAGEWIDTH - insertCoinTxt.width) - 48, Config.STAGEHEIGHT - 48);
        this.stage.addChild(insertCoinTxt);

        let creditsTxt = this.creditsTxt = new Text("CREDITS " + Datas.lives, { fontFamily: Config.DEFAULT_FONT, fill: 0xDDDDDD, fontSize: 24, letterSpacing: 4 });
        creditsTxt.position.set(48, Config.STAGEHEIGHT - 48);
        this.stage.addChild(creditsTxt);

        this.stage.addChild(Datas.atlas[Datas.FG]);

        let bestTxt = new Text("BEST " + BT.pad0(Save.get('best1500').toString(), 4), { fontFamily: Config.DEFAULT_FONT, fill: 0xDDDDDD, fontSize: 24, letterSpacing: 4 });
        bestTxt.position.set(Math.floor((Config.STAGEWIDTH - bestTxt.width) / 2), Math.floor(Config.STAGEHEIGHT / 3) - 56);
        this.stage.addChild(bestTxt);

        let credits = new Text("YopSolo - 2021 - v1.1", { fontFamily: Config.DEFAULT_FONT, fill: 0xDDDDDD, fontSize: 10, letterSpacing: 4 });
        credits.position.set(10, 10);
        this.stage.addChild(credits);

        let controls = new Sprite(Datas.atlas[Datas.CONTROLS]);
        controls.x = 805;
        controls.y = 333;
        this.stage.addChild(controls);
        
        this.player = new PlatformPlayer(
            this.gameInput1,
            32 - 16, 0 - 16,
            this);

        this.time = 0;
        this.startFlag = false;

        Datas.currentLevel = 1;
        Datas.lives = 0;

        let pc = this.pc = new ParticlesContainer(Datas.COIN2, 20);
        pc.config = 3;
        pc.position.set(titleTxt.x + titleTxt.width / 2, titleTxt.y + titleTxt.height / 2);
        this.stage.addChild(pc);

        this.stage.addChild(titleTxt);
        this.stage.addChild(startTxt);

        // lance la musique
        SoundManager.stop(Datas.SND_BGM);
        // lance la boucle de jeu (arretee par Main tant qu'aucun ecran n'est pret)
        BT.ticker.start();
    }

    end() {
        super.end();
    }

    onEnterFrame(pSeconds) {
        const pDt = pSeconds * Datas.DT_SCALE;
        this.time += pDt;
        // maj des input
        this.gameInput1.update(pSeconds);
        this.startTxt.visible = (Datas.lives >= 3);
        this.insertCoinTxt.alpha = (1 + Math.sin(this.time * 4)) * .5;
        // --
        this.pc.pickRan(75, 150, 75, .5);
        this.pc.update(pDt);

    };

    onEnterFrame2(pSeconds) {
        const pDt = pSeconds * Datas.DT_SCALE;
        this.time += pDt;
        // maj des input
        this.startTxt.visible = (Datas.lives >= 3);
        this.startTxt.alpha = (1 + Math.sin(this.time * 4)) * .5;
    };

    // on laisse 1.5 s a l'effet sonore de depart avant de quitter l'ecran
    transitionOut() {
        return super.transitionOut({ delay: 1.5 });
    }

    // appelee sur appui (front montant) : une pression = une piece, pas de drapeau anti-repetition
    playerAction(pValue) {
        if (pValue == GameInput.ACTION1) {
            if (Datas.lives < 3) {
                Datas.lives++;
                if (Datas.lives == 1) {
                    SoundManager.stop(Datas.SND_BGM);
                    SoundManager.play(Datas.SND_BGM);
                }
                this.creditsTxt.text = "CREDITS " + Datas.lives;
                this.flash(0xDEDEDE, 1, 3 / 4);
                SoundManager.play(Datas.SND_COIN);
            } else {
                if (!this.startFlag && Datas.lives == 3) {
                    this.startFlag = true;
                    this.onEnterFrame = this.onEnterFrame2;
                    this.insertCoinTxt.visible = false;
                    SoundManager.play(Datas.SND_START);
                    this.transitionOut();
                }
            }
        } else if (pValue == GameInput.ACTION2) {
            // --
        } else if (pValue == GameInput.ACTION3) {
            // --
        }
    }
}
