/**
 * Lecteur d'animations par clips nommes (logique pure, sans Pixi : testable et portable).
 *
 *   const player = new ClipPlayer({
 *       idle:   { frames: [t0] },                                  // 1 image
 *       run:    { frames: [t1, t2, t3, t4], fps: 9 },              // en boucle (loop: true par defaut)
 *       attack: { frames: [t5, t6, t7], fps: 14, loop: false, next: 'idle' }   // une fois, puis enchaine
 *   }, 'idle');
 *
 *   player.play('run');        // sans effet si 'run' joue deja (play('run', true) : repart du debut)
 *   player.update(dt);         // dt en secondes, a appeler a chaque frame (suit donc la pause du jeu)
 *   player.value;              // l'image courante (frames[index])
 *   player.onComplete = (name) => {...};   // fin d'un clip non boucle (apres le dernier temps d'affichage)
 *
 * Les "frames" peuvent etre n'importe quoi (textures Pixi, index...). Un clip non boucle sans `next` reste
 * sur sa derniere image (finished = true). player.speed multiplie la vitesse (ralenti, accelere).
 */
export class ClipPlayer {
    constructor(pClips, pInitial) {
        this.clips = pClips;
        this.name = null;
        this.index = 0;
        this.time = 0;          // secondes ecoulees dans le clip courant
        this.finished = false;
        this.speed = 1;
        this.onComplete = null;
        if (pInitial !== undefined) this.play(pInitial, true);
    }

    get clip() { return this.clips[this.name]; }
    get value() { return this.clip.frames[this.index]; }

    /** @returns true si le clip a change (ou a ete relance) */
    play(pName, pRestart = false) {
        if (pName === this.name && !pRestart) return false;
        if (!this.clips[pName]) throw new Error("ClipPlayer : clip inconnu '" + pName + "'");
        this.name = pName;
        this.index = 0;
        this.time = 0;
        this.finished = false;
        return true;
    }

    update(pDt) {
        const clip = this.clip;
        const n = clip.frames.length;
        if (n <= 1 || this.finished) {
            // un clip d'une image ne "finit" que s'il est non boucle ; on laisse le temps passer pour onComplete
            if (n <= 1 && clip.loop === false && !this.finished) this._advance(pDt, clip, n);
            return;
        }
        this._advance(pDt, clip, n);
    }

    _advance(pDt, clip, n) {
        this.time += pDt * this.speed;
        const fps = clip.fps || 10;
        const raw = Math.floor(this.time * fps);
        if (clip.loop === false) {
            if (raw >= n) {
                this.index = n - 1;
                this.finished = true;
                const name = this.name;
                if (clip.next) this.play(clip.next, true);
                if (this.onComplete) this.onComplete(name);
            } else {
                this.index = raw;
            }
        } else {
            this.index = raw % n;
        }
    }
}
