import { Container, Sprite } from '../../../core/fff.js';
import { Datas } from '../../../engine/Datas.js';
import { SATPolygon } from '../../../utils/SAT.js';

export class Door extends Container {
    constructor(pL, pC) {
        super();
        
        this.eventMode = 'none';

        let bb = this.bb = SATPolygon.CreatePolygon(4, 1);
        bb.x = (pC * 32);
        bb.y = (pL * 32) + 3;

        this.active = false;

        this.x = bb.x;
        this.y = bb.y - 4;

        
        this.sp = new Sprite(Datas.atlas[Datas.DOOR_C]);
        this.sp.anchor.set(.5);
        this.sp.scale.set(2,2);
        this.addChild(this.sp);
        this.sp.visible = true;

        this.sp2 = new Sprite(Datas.atlas[Datas.DOOR_O]);
        this.sp2.anchor.set(.5);
        this.sp2.scale.set(2,2);
        this.addChild(this.sp2);
        this.sp2.visible = false;
    }

    activate(){
        if(this.active == false)
        {
            this.active = true;
            this.sp.visible = false;
            this.sp2.visible = true;                 
        }
    }

    deactivate() {
        if (this.active == true) {
            this.active = false;
            this.sp.visible = true;
            this.sp2.visible = false;
        }
    }

}