import { gsap } from 'gsap';
import { Text } from '../core/fff.js';

/**
 * Petits textes flottants ("+100", "-1", "COMBO x3"...) : le texte monte, puis s'efface.
 * Les Text sont recycles (pool) : creer/detruire un Text par ramassage coute cher en GPU.
 *
 *   const popups = new PopupText(layer, { fontFamily: 'm04', fill: 0xFFFF55, fontSize: 16 });
 *   popups.show('+100', player.x, player.y - 20);
 */
export class PopupText {
    /**
     * @param pParent    Container qui recevra les textes (idealement au-dessus du decor)
     * @param pStyle     style de texte Pixi
     * @param pPoolSize  nombre max de popups simultanes (le plus ancien est reutilise au-dela)
     */
    constructor(pParent, pStyle, pPoolSize = 8) {
        this.parent = pParent;
        this._pool = [];
        for (let i = 0; i < pPoolSize; i++) {
            const t = new Text('', pStyle);
            t.anchor.set(.5, .5);
            t.eventMode = 'none';
            t.visible = false;
            pParent.addChild(t);
            this._pool.push(t);
        }
        this._next = 0;
    }

    /**
     * @param pValue texte ou nombre a afficher
     * @param pOptions { rise (px, defaut 36), duration (s, defaut .7), tint (couleur) }
     */
    show(pValue, pX, pY, pOptions = {}) {
        const { rise = 36, duration = .7, tint = 0xFFFFFF } = pOptions;
        const t = this._pool[this._next];
        this._next = (this._next + 1) % this._pool.length;

        gsap.killTweensOf(t);
        t.text = String(pValue);
        t.tint = tint;
        t.x = pX;
        t.y = pY;
        t.alpha = 1;
        t.scale.set(.6);
        t.visible = true;
        // remet au premier plan : un popup recycle ne doit pas rester sous le decor
        if (t.parent) t.parent.addChild(t);

        gsap.to(t.scale, { x: 1, y: 1, duration: .15, ease: 'back.out(3)' });
        gsap.to(t, { y: pY - rise, duration, ease: 'power2.out' });
        gsap.to(t, {
            alpha: 0, duration: duration * .4, delay: duration * .6, ease: 'none',
            onComplete: () => { t.visible = false; }
        });
        return t;
    }

    destroy() {
        this._pool.forEach((t) => { gsap.killTweensOf(t); gsap.killTweensOf(t.scale); });
        this._pool.length = 0;
    }
}
