import { Container, Sprite } from '../../../core/fff.js';
import { Datas } from '../../../engine/Datas.js';

export class TileItem extends Container {
    constructor(pL, pC, pTextureId, pTint = -1) {
        super();

        this.eventMode = 'none';

        this.lig = pL;
        this.col = pC;

        this.x = pC * 32;
        this.y = (pL * 32) + 8;

        this.sp = new Sprite(Datas.atlas[pTextureId]);
        this.sp.anchor.set(.5);
        this.addChild(this.sp);

        if(pTint > -1){
            this.sp.tint = pTint;
        }
    }
}