import { Container, Graphics } from '../core/fff.js';

const COLOR = 0xFFFF00;
const WIDTH = 2;

/**
 * Calque de debug : trace les collisions en jaune (trait de 2 px).
 * F2 (ou ?debug dans l'URL au demarrage) l'affiche / le masque.
 *
 *   const dbg = new CollisionDebug();
 *   container.addChild(dbg);                 // au-dessus de tout, dans le repere du niveau
 *   dbg.setGrid(grid);                       // tuiles pleines (dessinees une seule fois)
 *   dbg.update({ boxes: [body], circles: [player.bb], polygons: [door.bb.vertices] }); // chaque frame
 *
 * boxes : { x, y, hw, hh } (centre + demi-dimensions) ; circles : { x, y, radius } ;
 * polygons : tableaux de sommets { x, y } en coordonnees monde.
 */
export class CollisionDebug extends Container {
    constructor(pKeyCode = 'F2') {
        super();
        this.eventMode = 'none';
        this._grid = new Graphics();
        this._dyn = new Graphics();
        this.addChild(this._grid, this._dyn);

        this.enabled = new URLSearchParams(window.location.search).has('debug');
        this.visible = this.enabled;

        this._onKey = (e) => {
            if (e.code !== pKeyCode) return;
            e.preventDefault();
            this.enabled = !this.enabled;
            this.visible = this.enabled;
        };
        document.addEventListener('keydown', this._onKey);
    }

    /** trace les contours des tuiles pleines (TileGrid) */
    setGrid(pGrid) {
        const g = this._grid.clear();
        for (let r = 0; r < pGrid.rows; r++) {
            for (let c = 0; c < pGrid.cols; c++) {
                const t = pGrid.rectAt(c, r);
                if (t) g.rect(t.x0, t.y0, t.x1 - t.x0, t.y1 - t.y0);
            }
        }
        g.stroke({ width: WIDTH, color: COLOR });
    }

    /** a appeler a chaque frame (ne fait rien tant que le calque est masque) */
    update({ boxes = [], circles = [], polygons = [] } = {}) {
        if (!this.visible) return;
        const g = this._dyn.clear();
        boxes.forEach((b) => g.rect(b.x - b.hw, b.y - b.hh, b.hw * 2, b.hh * 2));
        circles.forEach((c) => g.circle(c.x, c.y, c.radius));
        polygons.forEach((vs) => {
            if (!vs || !vs.length) return;
            g.moveTo(vs[0].x, vs[0].y);
            for (let i = 1; i < vs.length; i++) g.lineTo(vs[i].x, vs[i].y);
            g.closePath();
        });
        g.stroke({ width: WIDTH, color: COLOR });
    }

    destroy(pOptions) {
        document.removeEventListener('keydown', this._onKey);
        super.destroy(pOptions);
    }
}
