import { Container, Sprite } from '../core/fff.js';
import { BT } from './BT.js';
import { Datas } from './Datas.js';

/**
 * Pool de particules simples (sprites recycles). `config` choisit le comportement :
 * 1 = deplacement, 2 = fondu, 3 = fondu + rotation, 4 = "poof" (fondu rapide).
 */
export class ParticlesContainer extends Container {
    constructor(pDatasTextureName, pPoolSize = 20) {
        super();
        this.config = 1;
        this._particlePool = [];
        for (let i = 0; i < pPoolSize; i++) {
            let p = new Particle(Datas.atlas[pDatasTextureName]);
            this._particlePool.push(p);
            this.addChild(p); // rempli avec N particules invisibles
        }
    }

    pick(pTTL, pVelX, pVelY, pOrigin, pScaleX, pScaleY) {
        let size = this._particlePool.length;
        for (let i = 0; i < size; i++) {
            let p = this._particlePool[i];
            if (p.active == false) {
                let p = this._particlePool[i];
                p.init(pTTL, pVelX, pVelY, pOrigin, pScaleX, pScaleY);
                return p;
            }
        }
        return this._particlePool[0];
    }

    pickRan(pMaxTTL, pRanVel, pRanOrigin, pRanScale) {
        let size = this._particlePool.length;
        for (let i = 0; i < size; i++) {
            let p = this._particlePool[i];
            if (p.active == false) {
                let p = this._particlePool[i];
                p.initRan(pMaxTTL, pRanVel, pRanOrigin, pRanScale);
                return p;
            }
        }
        return this._particlePool[0];
    }    

    update(pDt) {
        let size = this._particlePool.length;
        for (let i = 0; i < size; i++) {
            let p = this._particlePool[i];
            if (p.active) {
                if(this.config == 2){
                    p.updateAlpha(pDt);
                }else if(this.config == 3){
                    p.updateAlphaRotation(pDt);
                }else if(this.config == 4){
                    p.updatePoof(pDt);
                }else{
                    p.update(pDt);
                }
            }
        }
    }
}

class Particle extends Sprite {
    constructor(pDatasTexture) {
        super(pDatasTexture);
        this.anchor.set(.5, .5);
        this.pivot.set(.5, .5);
        this.active = false;
        this.visible = false;
        this._vx = 0;
        this._vy = 0;
    }

    init(pTTL, pVelX, pVelY, pOrigin, pScaleX, pScaleY) {
        this.active = true;
        this.alpha = 1;
        this.visible = true;
        this.scale.set(pScaleX, pScaleY);
        this.rotation = 0;

        this.position.set(pOrigin, pOrigin);
        this.ttl = pTTL;
        
        this._vx = pVelX;
        this._vy = pVelY;
    }

    initRan(pMaxTTL, pRanVel, pRanOrigin, pRanScale = 1) {
        if(pRanOrigin<1){
            pRanOrigin = 1;
        }
        if(pRanVel<1){
            pRanVel = 1;
        }

        this.active = true;
        this.alpha = 1;
        this.visible = true;
        let ranScale = (pRanScale == 1) ? 1 : BT.getRandomFloat(1 - pRanScale, 1 + pRanScale);
        this.scale.set(ranScale, ranScale);
        this.rotation = 0;

        let a = Math.random() * (2 * Math.PI);
        let ranX = Math.cos(a);
        let ranY = Math.sin(a);

        this.position.set(ranX * pRanOrigin, ranY * pRanOrigin);
        this.ttl = BT.getRandomInt( pMaxTTL/10, pMaxTTL);
        
        let len = Math.sqrt((this.position.x * this.position.x) + (this.position.y * this.position.y));
        this._vx = (this.position.x /len) * BT.getRandomFloat(1, pRanVel);
        this._vy = (this.position.y /len) * BT.getRandomFloat(1, pRanVel);
    }

    update(pDt) {
        this.ttl--;
        if (this.ttl > 0) {
            this._vx *= .95;
            this._vy *= .95;
            this.x += this._vx * pDt;
            this.y += this._vy * pDt;
        } else {
            this.active = false;
            this.visible = false;
        }
    }    

    updatePoof(pDt) {
        this.ttl--;
        if (this.ttl > 0) {
            this._vx *= .95;
            this._vy *= .95;
            this.x += this._vx * pDt;
            this.y += this._vy * pDt;
            this.alpha *= .9;
        } else {
            this.active = false;
            this.visible = false;
        }
    }       

    updateAlpha(pDt) {
        this.ttl--;
        if (this.ttl > 0) {
            this._vx *= .95;
            this._vy *= .95;
            this.x += this._vx * pDt;
            this.y += this._vy * pDt;
            this.alpha *= .95;
        } else {
            this.active = false;
            this.visible = false;
        }
    }     

    updateAlphaRotation(pDt) {
        this.ttl--;
        if (this.ttl > 0) {
            this._vx *= .95;
            this._vy *= .95;
            this.alpha *= .95;
            this.x += this._vx * pDt;
            this.y += this._vy * pDt;
            this.rotation += this._vx / 10 * pDt;
        } else {
            this.active = false;
            this.visible = false;
        }
    }
}